import { Link } from "react-router-dom";
import React, { useEffect, useState } from "react";
import PropTypes from "prop-types";
import { getAllCars, deleteCarById } from "../../services/ApiCar";

export default function CardVoiture({ color }) {
  const [Cars, setCars] = useState([]);

  const getcars = async () => {
    try {
      const res = await getAllCars();
      console.log("data");
      setCars(res.data);
      console.log(res.data);
    } catch (error) {
      console.log(error);
    }
  };

  const deleteCar = async (id) => {
    try {
      await deleteCarById(id);
      getcars();
    } catch (error) {
      console.log(error);
    }
  };

  useEffect(() => {
    getcars();
  }, []);

  return (
    <div
      className={`relative flex flex-col min-w-0 break-words w-full mb-6 shadow-lg rounded ${color === "light" ? "bg-white" : "bg-lightBlue-900 text-white"
        }`}
    >
      <div className="rounded-t mb-0 px-4 py-3 border-0">
        <div className="flex flex-wrap items-center">
          <div className="relative w-full px-4 max-w-full flex-grow flex-1">
            <h3
              className={`font-semibold text-lg ${color === "light" ? "text-blueGray-700" : "text-white"
                }`}
            >
              Voiture Tables
            </h3>
          </div>
        </div>
      </div>
      <div className="block w-full overflow-x-auto">
        <table className="items-center w-full bg-transparent border-collapse">
          <thead>
            <tr>
              <th className="px-6 py-3 text-left text-xs font-semibold uppercase text-blueGray-500">Model</th>
              <th className="px-6 py-3 text-left text-xs font-semibold uppercase text-blueGray-500">Matricule</th>
              <th className="px-6 py-3 text-left text-xs font-semibold uppercase text-blueGray-500">Prix</th>
              <th className="px-6 py-3 text-left text-xs font-semibold uppercase text-blueGray-500">CreatedAt</th>
              <th
                className={`px-6 align-middle border border-solid py-3 text-xs uppercase border-l-0 border-r-0 whitespace-nowrap font-semibold ${color === "light"
                  ? "bg-blueGray-50 text-blueGray-500 border-blueGray-100"
                  : "bg-lightBlue-800 text-lightBlue-300 border-lightBlue-700"
                  } text-center`}
              >
                Actions
              </th>
            </tr>
          </thead>
          <tbody>
            {Cars.map((car, index) => (
              <tr
                key={index}
                className={`${index % 2 === 0 ? "bg-gray-50" : "bg-white"} border-b border-gray-200`}
              >
                <td className="px-6 py-4 text-sm">{car.model}</td>
                <td className="px-6 py-4 text-sm">{car.matricule}</td>
                <td className="px-6 py-4 text-sm">{car.prix}</td>
                <td className="px-6 py-4 text-sm">{car.createdAt}</td>
                <td className="px-6 py-4 text-sm">
                  <div className="flex gap-2 justify-center">
                    <Link to="/admin/AddVoiture">
                      <button className="bg-emerald-500 hover:bg-emerald-600 text-white font-semibold text-sm px-4 py-2 rounded-full shadow-md transition duration-200">
                        ➕ Add
                      </button>
                    </Link>
                    <Link to={`/admin/update-voiture/${car._id}`}>
                      <button className="bg-yellow-400 hover:bg-yellow-500 text-white font-semibold text-sm px-4 py-2 rounded-full shadow-md transition duration-200">
                        ✏️ Update
                      </button>
                    </Link>
                    <button
                      className="bg-red-500 hover:bg-red-600 text-white font-semibold text-sm px-4 py-2 rounded-full shadow-md transition duration-200"
                      onClick={() => deleteCar(car._id)}
                    >
                      🗑️ Delete
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

CardVoiture.defaultProps = {
  color: "light",
};

CardVoiture.propTypes = {
  color: PropTypes.oneOf(["light", "dark"]),
};
